<?php
require_once __DIR__.'/includes/app.php';$id=filter_input(INPUT_GET,'id',FILTER_VALIDATE_INT)?:0;$st=db()->prepare('SELECT * FROM products WHERE id=? AND is_active=1');$st->execute([$id]);$p=$st->fetch();if(!$p){http_response_code(404);render_header('Produit introuvable');?><section class="container empty-state page-empty"><h1>Produit introuvable</h1><p>Ce produit n’est plus disponible.</p><a class="button button-primary" href="index.php">Retour à la boutique</a></section><?php render_footer();exit;}render_header($p['name']);?>
<section class="container product-detail"><div class="detail-image"><img src="<?=e(product_image($p['image']))?>" alt="<?=e($p['name'])?>"></div><div class="detail-copy"><a class="back-link" href="index.php#produits">← Retour à la boutique</a><span class="eyebrow"><?=e($p['category'])?></span><h1><?=e($p['name'])?></h1><div class="detail-price"><?=money($p['price'])?></div><p class="detail-description"><?=nl2br(e($p['description']?:'Un produit de qualité, sélectionné pour vous accompagner au quotidien.'))?></p><p class="stock-line <?=(int)$p['stock']>0?'in-stock':'out-of-stock'?>"><?=(int)$p['stock']>0?'✓ En stock — '.(int)$p['stock'].' disponible(s)':'Rupture de stock'?></p><?php if((int)$p['stock']>0):?><form action="cart.php" method="post" class="detail-form"><?=csrf_field()?><input type="hidden" name="action" value="add"><input type="hidden" name="product_id" value="<?=(int)$p['id']?>"><label>Quantité<input type="number" name="quantity" min="1" max="<?=(int)$p['stock']?>" value="1"></label><button class="button button-primary">Ajouter au panier <span>→</span></button></form><?php endif;?></div></section><?php render_footer();?>
